#include <iostream>

int main() {
    int a = 17, b = 5;
    std::cout << a / b << ' ' << a % b << ' '
              << a / 5.0 << std::endl;

    a += 3;
    std::cout << a << std::endl;

    bool big = (a > 20);
    std::cout << (a > 5 && b > 0) << ' ' << !big << ' ' << a << std::endl;
    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    double pi = 3.14159;
    std::cout << "pi = " << pi << std::endl;
    std::cout << "pi = " << std::fixed << std::setprecision(2) << pi << std::endl;
    return 0;
}

