#include <iostream>

int main() {
    int total = 17, count = 4;
    std::cout << total / count << std::endl;
    std::cout << static_cast<double>(total) / count << std::endl;

    char letter = 'A';
    std::cout << static_cast<int>(letter) << ' '
              << static_cast<char>(letter + 2) << std::endl;
    return 0;
}
